/**
 * @fileoverview Tests for strict rule.
 * @author Nicholas C. Zakas
 */

"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const rule = require("../../../lib/rules/strict"),
	RuleTester = require("../../../lib/rule-tester/rule-tester");

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

const ruleTester = new RuleTester({
	languageOptions: {
		ecmaVersion: 5,
		sourceType: "script",
	},
});

ruleTester.run("strict", rule, {
	valid: [
		// "never" mode
		{ code: "foo();", options: ["never"] },
		{ code: "function foo() { return; }", options: ["never"] },
		{ code: "var foo = function() { return; };", options: ["never"] },
		{ code: "foo(); 'use strict';", options: ["never"] },
		{
			code: "function foo() { bar(); 'use strict'; return; }",
			options: ["never"],
		},
		{
			code: "var foo = function() { { 'use strict'; } return; };",
			options: ["never"],
		},
		{
			code: "(function() { bar('use strict'); return; }());",
			options: ["never"],
		},
		{
			code: "var fn = x => 1;",
			options: ["never"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "var fn = x => { return; };",
			options: ["never"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "foo();",
			options: ["never"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
		},
		{
			code: "function foo() { return; }",
			options: ["never"],
			languageOptions: {
				parserOptions: { ecmaFeatures: { impliedStrict: true } },
			},
		},

		// "global" mode
		{ code: "// Intentionally empty", options: ["global"] },
		{ code: '"use strict"; foo();', options: ["global"] },
		{
			code: "/* license */\n/* eslint-disable rule-to-test/strict */\nfoo();",
			options: ["global"],
		},
		{
			code: "foo();",
			options: ["global"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
		},
		{
			code: "function foo() { return; }",
			options: ["global"],
			languageOptions: {
				parserOptions: { ecmaFeatures: { impliedStrict: true } },
			},
		},
		{
			code: "'use strict'; function foo() { return; }",
			options: ["global"],
		},
		{
			code: "'use strict'; var foo = function() { return; };",
			options: ["global"],
		},
		{
			code: "'use strict'; function foo() { bar(); 'use strict'; return; }",
			options: ["global"],
		},
		{
			code: "'use strict'; var foo = function() { bar(); 'use strict'; return; };",
			options: ["global"],
		},
		{
			code: "'use strict'; function foo() { return function() { bar(); 'use strict'; return; }; }",
			options: ["global"],
		},
		{
			code: "'use strict'; var foo = () => { return () => { bar(); 'use strict'; return; }; }",
			options: ["global"],
			languageOptions: { ecmaVersion: 6 },
		},

		// "function" mode
		{
			code: "function foo() { 'use strict'; return; }",
			options: ["function"],
		},
		{
			code: "function foo() { return; }",
			options: ["function"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
		},
		{
			code: "function foo() { return; }",
			options: ["function"],
			languageOptions: {
				parserOptions: { ecmaFeatures: { impliedStrict: true } },
			},
		},
		{
			code: "var foo = function() { return; }",
			options: ["function"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
		},
		{
			code: "var foo = function() { 'use strict'; return; }",
			options: ["function"],
		},
		{
			code: "function foo() { 'use strict'; return; } var bar = function() { 'use strict'; bar(); };",
			options: ["function"],
		},
		{
			code: "var foo = function() { 'use strict'; function bar() { return; } bar(); };",
			options: ["function"],
		},
		{
			code: "var foo = () => { 'use strict'; var bar = () => 1; bar(); };",
			options: ["function"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "var foo = () => { var bar = () => 1; bar(); };",
			options: ["function"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
		},
		{
			code: "class A { constructor() { } }",
			options: ["function"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "class A { foo() { } }",
			options: ["function"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "class A { foo() { function bar() { } } }",
			options: ["function"],
			languageOptions: { ecmaVersion: 6 },
		},
		{
			code: "(function() { 'use strict'; function foo(a = 0) { } }())",
			options: ["function"],
			languageOptions: { ecmaVersion: 6 },
		},

		// "safe" mode corresponds to "global" if ecmaFeatures.globalReturn is true, otherwise "function"
		{ code: "function foo() { 'use strict'; return; }", options: ["safe"] },
		{
			code: "'use strict'; function foo() { return; }",
			options: ["safe"],
			languageOptions: {
				parserOptions: { ecmaFeatures: { globalReturn: true } },
			},
		},
		{
			code: "function foo() { return; }",
			options: ["safe"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
		},
		{
			code: "function foo() { return; }",
			options: ["safe"],
			languageOptions: {
				parserOptions: { ecmaFeatures: { impliedStrict: true } },
			},
		},

		// defaults to "safe" mode
		"function foo() { 'use strict'; return; }",
		{
			code: "'use strict'; function foo() { return; }",
			languageOptions: {
				parserOptions: { ecmaFeatures: { globalReturn: true } },
			},
		},
		{
			code: "function foo() { return; }",
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
		},
		{
			code: "function foo() { return; }",
			languageOptions: {
				parserOptions: { ecmaFeatures: { impliedStrict: true } },
			},
		},

		// class static blocks do not have directive prologues, therefore this rule should never require od disallow "use strict" statement in them.
		{
			code: "'use strict'; class C { static { foo; } }",
			options: ["global"],
			languageOptions: { ecmaVersion: 2022 },
		},
		{
			code: "'use strict'; class C { static { 'use strict'; } }",
			options: ["global"],
			languageOptions: { ecmaVersion: 2022 },
		},
		{
			code: "'use strict'; class C { static { 'use strict'; 'use strict'; } }",
			options: ["global"],
			languageOptions: { ecmaVersion: 2022 },
		},
		{
			code: "class C { static { foo; } }",
			options: ["function"],
			languageOptions: { ecmaVersion: 2022 },
		},
		{
			code: "class C { static { 'use strict'; } }",
			options: ["function"],
			languageOptions: { ecmaVersion: 2022 },
		},
		{
			code: "class C { static { 'use strict'; 'use strict'; } }",
			options: ["function"],
			languageOptions: { ecmaVersion: 2022 },
		},
		{
			code: "class C { static { foo; } }",
			options: ["never"],
			languageOptions: { ecmaVersion: 2022 },
		},
		{
			code: "class C { static { 'use strict'; } }",
			options: ["never"],
			languageOptions: { ecmaVersion: 2022 },
		},
		{
			code: "class C { static { 'use strict'; 'use strict'; } }",
			options: ["never"],
			languageOptions: { ecmaVersion: 2022 },
		},
		{
			code: "class C { static { 'use strict'; } }",
			options: ["safe"],
			languageOptions: { ecmaVersion: 2022, sourceType: "module" },
		},
		{
			code: "class C { static { 'use strict'; } }",
			options: ["safe"],
			languageOptions: {
				ecmaVersion: 2022,
				parserOptions: { ecmaFeatures: { impliedStrict: true } },
			},
		},
		{
			code: "'use strict'; module.exports = function identity (value) { return value; }",
			languageOptions: {
				sourceType: "commonjs",
			},
		},
		{
			code: "'use strict'; module.exports = function identity (value) { return value; }",
			options: ["safe"],
			languageOptions: {
				sourceType: "commonjs",
			},
		},
	],
	invalid: [
		// "never" mode
		{
			code: '"use strict"; foo();',
			output: null,
			options: ["never"],
			errors: [
				{
					messageId: "never",
				},
			],
		},
		{
			code: "function foo() { 'use strict'; return; }",
			output: null,
			options: ["never"],
			errors: [
				{
					messageId: "never",
				},
			],
		},
		{
			code: "var foo = function() { 'use strict'; return; };",
			output: null,
			options: ["never"],
			errors: [
				{
					messageId: "never",
				},
			],
		},
		{
			code: "function foo() { return function() { 'use strict'; return; }; }",
			output: null,
			options: ["never"],
			errors: [
				{
					messageId: "never",
				},
			],
		},
		{
			code: "'use strict'; function foo() { \"use strict\"; return; }",
			output: null,
			options: ["never"],
			errors: [
				{
					messageId: "never",
				},
				{
					messageId: "never",
				},
			],
		},
		{
			code: '"use strict"; foo();',
			output: " foo();",
			options: ["never"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "module",
				},
			],
		},
		{
			code: "'use strict'; function foo() { 'use strict'; return; }",
			output: " function foo() {  return; }",
			options: ["never"],
			languageOptions: {
				parserOptions: { ecmaFeatures: { impliedStrict: true } },
			},
			errors: [
				{
					messageId: "implied",
				},
				{
					messageId: "implied",
				},
			],
		},
		{
			code: "'use strict'; function foo() { 'use strict'; return; }",
			output: " function foo() {  return; }",
			options: ["never"],
			languageOptions: {
				ecmaVersion: 6,
				sourceType: "module",
				parserOptions: { ecmaFeatures: { impliedStrict: true } },
			},
			errors: [
				{
					messageId: "module",
				},
				{
					messageId: "module",
				},
			],
		},

		// "global" mode
		{
			code: "foo();",
			output: null,
			options: ["global"],
			errors: [
				{
					messageId: "global",
				},
			],
		},
		{
			code: "/* license */\nfunction foo() {}\nfunction bar() {}\n/* end */",
			output: null,
			options: ["global"],
			errors: [
				{
					messageId: "global",
					line: 2,
					column: 1,
					endLine: 3,
					endColumn: 18,
				},
			],
		},
		{
			code: "function foo() { 'use strict'; return; }",
			output: null,
			options: ["global"],
			errors: [
				{
					messageId: "global",
				},
				{
					messageId: "global",
				},
			],
		},
		{
			code: "var foo = function() { 'use strict'; return; }",
			output: null,
			options: ["global"],
			errors: [
				{
					messageId: "global",
				},
				{
					messageId: "global",
				},
			],
		},
		{
			code: "var foo = () => { 'use strict'; return () => 1; }",
			output: null,
			options: ["global"],
			languageOptions: { ecmaVersion: 6 },
			errors: [
				{
					messageId: "global",
				},
				{
					messageId: "global",
				},
			],
		},
		{
			code: "'use strict'; function foo() { 'use strict'; return; }",
			output: null,
			options: ["global"],
			errors: [
				{
					messageId: "global",
				},
			],
		},
		{
			code: "'use strict'; var foo = function() { 'use strict'; return; };",
			output: null,
			options: ["global"],
			errors: [
				{
					messageId: "global",
				},
			],
		},
		{
			code: "'use strict'; 'use strict'; foo();",
			output: "'use strict';  foo();",
			options: ["global"],
			errors: [
				{
					messageId: "multiple",
				},
			],
		},
		{
			code: "'use strict'; foo();",
			output: " foo();",
			options: ["global"],
			languageOptions: { ecmaVersion: 6, sourceType: "module" },
			errors: [
				{
					messageId: "module",
				},
			],
		},
		{
			code: "'use strict'; function foo() { 'use strict'; return; }",
			output: " function foo() {  return; }",
			options: ["global"],
			languageOptions: {
				parserOptions: { ecmaFeatures: { impliedStrict: true } },
			},
			errors: [
				{
					messageId: "implied",
				},
				{
					messageId: "implied",
				},
			],
		},
		{
			code: "'use strict'; function foo() { 'use strict'; return; }",
			output: " function foo() {  return; }",
			options: ["global"],
			languageOptions: {
				ecmaVersion: 6,
				sourceType: "module",
				parserOptions: { ecmaFeatures: { impliedStrict: true } },
			},
			errors: [
				{
					messageId: "module",
				},
				{
					messageId: "module",
